effect.shader:
const float TAU = 6.28318530718;

void main() {
    vec2 offset = (acScreenNorm - center) * vec2(acAspect, 1.0);
    float dist = length(offset);

    float wave = sin(dist * frequency - acTime * speed * TAU) * amplitude * 0.004;
    float falloff = 1.0 - smoothstep(0.0, max(radius, 0.001), dist);

    // No centro exato não existe direção: dividir por zero produziria NaN, e um
    // NaN na coordenada de amostragem vira um pixel de lixo bem no meio.
    vec2 direction = dist > 0.0001 ? offset / dist : vec2(0.0);
    vec2 shift = direction * wave * falloff;
    shift /= vec2(acAspect, 1.0);

    fragColor = texture(inputImg, clamp(acScreenNorm + shift, 0.0, 1.0));
}
